  sum+=std::uint64_t(x.numerator())^std::uint64_t(x.denominator());
 }
 const auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-begin).count();
 std::cout<<ns<<' '<<sum<<'\n';
}

