from pathlib import Path
import subprocess,json,random,statistics,fcntl
p=Path(__file__).parent;lock=open('/tmp/sirkit_performance_cpu8.lock','w');fcntl.flock(lock,fcntl.LOCK_EX)
s=(p/'bench_large.cpp').read_text().replace('for(int rep=0;rep<8;++rep)','for(int rep=0;rep<(524288/count);++rep)')
(p/'bench_size.cpp').write_text(s)
variants=['baseline','parallel','parallel_diff'];raw=[];rng=random.Random(4561)
for native in [False,True]:
 for v in variants:
  cmd=['taskset','-c','8','/usr/bin/g++','-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',f'-DHEADER="{p/(v+".hpp")}"',str(p/'bench_size.cpp'),'-o',str(p/(('native-size-'if native else'default-size-')+v))]
  if native:cmd+=['-march=native']
  q=subprocess.run(cmd,text=True,capture_output=True);assert q.returncode==0,q.stderr
 for count in [32,262144]:
  for kind,mode in [(k,m)for k in [0,1]for m in [0,2,4]]:
   for rep in range(5):
    order=variants+['control'];rng.shuffle(order)
    for v in order:
     source=p/(('native-size-'if native else'default-size-')+('baseline'if v=='control'else v))
     with (p/'run').open('wb')as f:f.write(source.read_bytes())
     (p/'run').chmod(0o755)
     q=subprocess.run(['taskset','-c','8',str(p/'run'),str(mode),str(kind),str(count)],capture_output=True,text=True);assert q.returncode==0,q.stderr
     ns,checksum=map(int,q.stdout.split());raw.append(dict(native=native,count=count,kind=kind,mode=mode,rep=rep,variant=v,ns=ns,checksum=checksum))
   rows=[x for x in raw if x['native']==native and x['count']==count and x['kind']==kind and x['mode']==mode];assert len({x['checksum']for x in rows})==1
   med={v:statistics.median(x['ns']for x in rows if x['variant']==v)for v in variants+['control']};print(native,count,kind,mode,{v:round(med[v]/med['baseline'],4)for v in med},flush=True)
   (p/'parallel-diff-raw.json').write_text(json.dumps(raw)+'\n')
summary=[]
for native in [False,True]:
 for count in [32,262144]:
  for kind,mode in [(k,m)for k in [0,1]for m in [0,2,4]]:
   rows=[x for x in raw if x['native']==native and x['count']==count and x['kind']==kind and x['mode']==mode];med={v:statistics.median(x['ns']for x in rows if x['variant']==v)for v in variants+['control']};summary.append(dict(native=native,count=count,kind=kind,mode=mode,median_ns=med,ratio={v:med[v]/med['baseline']for v in med}))
(p/'parallel-diff-summary.json').write_text(json.dumps(summary,indent=2)+'\n')

